 client=await connectCDP(chrome.port); await client.Page.enable();await client.Runtime.enable();
 for(const [name,v] of Object.entries(config.videos)){
  if(selected.length&&!selected.includes(name))continue;
  console.log('Preparing',name);
  const zoom=v.zoom??1,width=1600,height=900;
  await client.Emulation.clearDeviceMetricsOverride();
  await client.Emulation.setDeviceMetricsOverride({width:Math.round(width/zoom),height:Math.round(height/zoom),deviceScaleFactor:zoom,mobile:false});
  await navigate(client,v.url);await waitForSelector(client,v.waitFor);await pause(2200);
