  const ctx=new RecordingContext();ctx.setMode('record');ctx.setCursorPosition(80,80);
  const timeline=new InteractionTimeline(width,height,{fps:v.fps,zoom,autoZoom:false,background:'none',hud:{enabled:false},initialCursor:{x:80,y:80}});ctx.setTimeline(timeline);
