  const raw=resolve(dir,'.yyoreel/raw',name+'.mp4');moveFileSync(recorder.getTempVideoPath(),raw);recorder=null;
  writeFileSync(resolve(dir,'.yyoreel/timelines',name+'.timeline.json'),JSON.stringify(data));await compose(raw,data,output,{crf:11,preset:'veryfast'});
  console.log('Done',output);
 }
